import { compile as compileJsonSchema } from "json-schema-to-typescript";
import prettier from "prettier";
import { toPascalCase } from "./utils.js";

const defaultBanner = [
  "/**",
  "* This file was automatically generated.",
  "*",
  "* Do not modify it by hand",
  "*/",
];

const defaultGoBanner = [
  "// Code generated by bson-compiler. DO NOT EDIT.",
  "",
];

const bsonToTs = new Map([
  ["number", { ts: "number" }],
  ["double", { ts: "number" }],
  ["string", { ts: "string" }],
  ["bool", { ts: "boolean" }],
  ["date", { ts: "Date" }],
  ["null", { ts: "null" }],
  ["int", { ts: "number" }],
  ["decimal", { ts: "Decimal128", import: "Decimal128" }],
  ["objectId", { ts: "ObjectId", import: "ObjectId" }],
  ["binData", { ts: "Binary", import: "Binary" }],
  ["long", { ts: "Long", import: "Long" }],
  ["timestamp", { ts: "Timestamp", import: "Timestamp" }],
  ["regex", { ts: "RegExp" }],
  ["javascript", { ts: "Code", import: "Code" }],
  ["javascriptWithScope", { ts: "Code", import: "Code" }],
  ["dbPointer", { ts: "DBRef", import: "DBRef" }],
  ["symbol", { ts: "BSONSymbol", import: "BSONSymbol" }],
  ["minKey", { ts: "MinKey", import: "MinKey" }],
  ["maxKey", { ts: "MaxKey", import: "MaxKey" }],
]);

const bsonToGo = new Map([
  ["number", { go: "float64" }],
  ["double", { go: "float64" }],
  ["string", { go: "string" }],
  ["bool", { go: "bool" }],
  ["date", { go: "time.Time", import: "time" }],
  ["null", { go: "interface{}" }],
  ["int", { go: "int" }],
  ["long", { go: "int64" }],
  [
    "decimal",
    {
      go: "primitive.Decimal128",
      import: "go.mongodb.org/mongo-driver/bson/primitive",
    },
  ],
  [
    "objectId",
    {
      go: "primitive.ObjectID",
      import: "go.mongodb.org/mongo-driver/bson/primitive",
    },
  ],
  ["binData", { go: "[]byte" }],
  [
    "timestamp",
    {
      go: "primitive.Timestamp",
      import: "go.mongodb.org/mongo-driver/bson/primitive",
    },
  ],
  [
    "regex",
    {
      go: "primitive.Regex",
      import: "go.mongodb.org/mongo-driver/bson/primitive",
    },
  ],
  ["javascript", { go: "string" }],
  ["javascriptWithScope", { go: "string" }],
  [
    "dbPointer",
    {
      go: "primitive.DBPointer",
      import: "go.mongodb.org/mongo-driver/bson/primitive",
    },
  ],
  ["symbol", { go: "string" }],
  ["minKey", { go: "interface{}" }],
  ["maxKey", { go: "interface{}" }],
  ["array", { go: "[]interface{}" }],
  ["object", { go: "map[string]interface{}" }],
]);

function formatTs(text, options) {
  return prettier.format(text, { ...(options || {}), parser: "typescript" });
}

function buildTsType(bsonType, imports) {
  if (Array.isArray(bsonType)) {
    return bsonType
      .map((b) => buildTsType(b, imports))
      .filter(Boolean)
      .join("|");
  }

  if (typeof bsonType !== "string") return null;

  const mapping = bsonToTs.get(bsonType);
  if (!mapping) return null;

  if (mapping.import) {
    imports.add(mapping.import);
  }

  return mapping.ts;
}

function buildGoType(bsonType, imports) {
  if (Array.isArray(bsonType)) {
    const filtered = bsonType.filter((b) => b !== "null");
    if (filtered.length === 1) return buildGoType(filtered[0], imports);
    return "interface{}";
  }

  if (typeof bsonType !== "string") return "interface{}";

  const mapping = bsonToGo.get(bsonType);
  if (!mapping) return "interface{}";

  if (mapping.import) {
    imports.add(mapping.import);
  }

  return mapping.go;
}

function setTsType(schema, imports) {
  if (Array.isArray(schema)) {
    return schema.map((s) => setTsType(s, imports));
  }

  if (typeof schema === "object" && schema !== null) {
    const bsonType = "bsonType" in schema ? schema.bsonType : undefined;
    const isEnum = Reflect.has(schema, "enum");
    const tsType = buildTsType(bsonType, imports);
    const annotated = !isEnum && tsType ? { ...schema, tsType } : schema;

    return Object.entries(annotated).reduce((acc, [key, value]) => {
      return { ...acc, [key]: setTsType(value, imports) };
    }, {});
  }

  return schema;
}

function resolveGoType(schema, imports) {
  if (!schema || typeof schema !== "object") return "interface{}";

  if (schema.bsonType === "array" && schema.items) {
    const inner = resolveGoType(schema.items, imports);
    return `[]${inner}`;
  }

  if (schema.bsonType === "object" && schema.properties) {
    return "map[string]interface{}";
  }

  return buildGoType(schema.bsonType, imports);
}

export async function compileBSONToTs(schema, options) {
  const imports = new Set();
  const newSchema = setTsType(schema, imports);

  const baseBanner = options?.bannerComment || defaultBanner;
  const mongoImports = [...imports];

  const bannerComment =
    mongoImports.length > 0
      ? [
          ...baseBanner,
          `import { ${mongoImports.sort().join(", ")} } from "mongodb";`,
        ]
      : baseBanner;

  const compileOptions = {
    bannerComment: bannerComment.join("\n"),
    enableConstEnums: options?.enableConstEnums,
    ignoreMinAndMaxItems: options?.ignoreMinAndMaxItems,
    strictIndexSignatures: options?.strictIndexSignatures,
    unknownAny: options?.unknownAny,
  };

  const output = await compileJsonSchema(newSchema, "", compileOptions);
  return formatTs(output, options?.prettier);
}

export function compileBSONToGo(schema, options) {
  const jsonSchema = schema?.$jsonSchema || schema;
  const properties = jsonSchema?.properties || {};
  const required = new Set(jsonSchema?.required || []);
  const imports = new Set();

  const fields = Object.entries(properties).map(([key, value]) => {
    const goType = resolveGoType(value, imports);
    const structField = toPascalCase(key);
    const isRequired = required.has(key);
    const forceOmitEmpty = key === "_id"; // allow Mongo to set _id server-side
    const suffix = isRequired && !forceOmitEmpty ? "" : ",omitempty";
    const tag = `\`bson:"${key}${suffix}" json:"${key}${suffix}"\``;
    return `  ${structField} ${goType} ${tag}`;
  });

  const banner = options?.bannerComment || defaultGoBanner;
  const packageName = options?.packageName || "models";
  const structName = options?.structName || "Document";
  const structOnly = Boolean(options?.structOnly);

  const baseImports = new Set(options?.imports || []);
  const importList = [...new Set([...imports, ...baseImports])].sort();

  const sections = [];

  if (!structOnly && banner.length > 0) {
    sections.push(banner.join("\n"));
  }

  if (!structOnly) {
    sections.push(`package ${packageName}`);
  }

  if (!structOnly && importList.length > 0) {
    const importBlock = ["import (", ...importList.map((i) => `  "${i}"`), ")"];
    sections.push(importBlock.join("\n"));
  }

  const structLines = [`type ${structName} struct {`, ...fields, `}`];
  sections.push(structLines.join("\n"));

  return sections.join("\n\n");
}
